#include "DictionaryReader.h"

#include <cstdint>
#include <cstring>
#include <string>
#include <vector>
#include <stdexcept>

namespace SharpVox {

	// STDICT version 2, generated by data/compile.py. All little-endian:
	//   0   4 bytes  magic "STDK"
	//   4   uint16   version (2)
	//   6   uint16   restart interval
	//   8   uint32   word count
	//  12   uint32   words offset
	//  16   uint32   words length
	//  20   uint32   phonemes offset
	//  24   uint32   phonemes length
	//
	// Entries are sorted by word. Each entry in the word stream is one byte
	// saying how many leading bytes it shares with the previous word, the rest
	// of the word, then WORD_END. Every restart-interval-th entry shares
	// nothing, so it can be read without looking at earlier entries.
	//
	// Each entry in the phoneme stream is its phonemes, then PHONS_END. A
	// stress marker is folded into the vowel after it: vowel + 64 for primary,
	// vowel + 128 for secondary.

	static const uint8_t WORD_END	      = 0x0A;
	static const uint8_t PHONS_END	      = 0xFF;
	static const uint8_t FOLD_PRIMARY     = 64;
	static const uint8_t FOLD_SECONDARY   = 128;
	static const uint8_t STRESS_PRIMARY   = 56;
	static const uint8_t STRESS_SECONDARY = 57;

	static uint32_t ReadU16LE(const uint8_t* data, int32_t off) {
		return (uint32_t)data[off] | ((uint32_t)data[off + 1] << 8);
	}

	static uint32_t ReadU32LE(const uint8_t* data, int32_t off) {
		return (uint32_t)data[off] | ((uint32_t)data[off + 1] << 8) | ((uint32_t)data[off + 2] << 16) | ((uint32_t)data[off + 3] << 24);
	}

	DictReader::DictReader(const uint8_t* data, int32_t dataLen)
	    : _data(data), _dataLen(dataLen), _wordCount(0), _restartInterval(1), _wordsEnd(0) {
		if(dataLen < 28 || data[0] != (uint8_t)'S' || data[1] != (uint8_t)'T' ||
		   data[2] != (uint8_t)'D' || data[3] != (uint8_t)'K') {
			throw std::runtime_error("Invalid STDICT magic");
		}
		if(ReadU16LE(data, 4) != 2) {
			throw std::runtime_error("Unsupported STDICT version");
		}

		_restartInterval = (int32_t)ReadU16LE(data, 6);
		_wordCount	 = (int32_t)ReadU32LE(data, 8);
		int32_t wordOff	 = (int32_t)ReadU32LE(data, 12);
		_wordsEnd	 = wordOff + (int32_t)ReadU32LE(data, 16);
		int32_t phonsOff = (int32_t)ReadU32LE(data, 20);

		_restarts.reserve((_wordCount + _restartInterval - 1) / _restartInterval);
		for(int32_t i = 0; i < _wordCount; i++) {
			if(i % _restartInterval == 0) {
				_restarts.push_back({(uint32_t)wordOff, (uint32_t)phonsOff});
			}
			wordOff++; // shared prefix length, which may itself equal WORD_END
			while(_data[wordOff] != WORD_END) {
				wordOff++;
			}
			wordOff++;
			while(_data[phonsOff] != PHONS_END) {
				phonsOff++;
			}
			phonsOff++;
		}
	}

	void DictReader::ReadEntry(int32_t& wordOff, int32_t& phonsOff, std::string& word, int32_t& entryPhonsOff) const {
		word.resize(_data[wordOff++]);
		while(_data[wordOff] != WORD_END) {
			word.push_back((char)_data[wordOff++]);
		}
		wordOff++;

		entryPhonsOff = phonsOff;
		while(_data[phonsOff] != PHONS_END) {
			phonsOff++;
		}
		phonsOff++;
	}

	std::vector<uint8_t> DictReader::UnfoldPhons(int32_t phonsOff) const {
		std::vector<uint8_t> phons;
		for(; _data[phonsOff] != PHONS_END; phonsOff++) {
			uint8_t b = _data[phonsOff];
			if(b >= FOLD_SECONDARY) {
				phons.push_back(STRESS_SECONDARY);
				phons.push_back(b - FOLD_SECONDARY);
			} else if(b >= FOLD_PRIMARY) {
				phons.push_back(STRESS_PRIMARY);
				phons.push_back(b - FOLD_PRIMARY);
			} else {
				phons.push_back(b);
			}
		}
		return phons;
	}

	// Compares word against the whole word stored at a restart entry.
	static int CompareRestartWord(const std::string& word, const uint8_t* stored) {
		const uint8_t* suffix = stored + 1; // prefix length is always 0 here
		size_t	       len    = static_cast<const uint8_t*>(memchr(suffix, WORD_END, 256)) - suffix;
		int	       cmp    = memcmp(word.data(), suffix, word.size() < len ? word.size() : len);
		if(cmp != 0) {
			return cmp;
		}
		return word.size() < len ? -1 : (word.size() > len ? 1 : 0);
	}

	std::vector<uint8_t> DictReader::Search(const std::string& word) const {
		if(_restarts.empty() || word.empty()) {
			return {};
		}

		// Find the last restart entry whose word is <= the target.
		int32_t lo = 0, hi = (int32_t)_restarts.size() - 1, found = -1;
		while(lo <= hi) {
			int32_t mid = (lo + hi) >> 1;
			int	cmp = CompareRestartWord(word, _data + _restarts[mid].word);
			if(cmp == 0) {
				return UnfoldPhons((int32_t)_restarts[mid].phons);
			}
			if(cmp > 0) {
				found = mid;
				lo    = mid + 1;
			} else {
				hi = mid - 1;
			}
		}
		if(found < 0) {
			return {};
		}

		int32_t	    wordOff  = (int32_t)_restarts[found].word;
		int32_t	    phonsOff = (int32_t)_restarts[found].phons;
		int32_t	    entryPhonsOff;
		std::string entry;
		for(int32_t i = 0; i < _restartInterval && wordOff < _wordsEnd; i++) {
			ReadEntry(wordOff, phonsOff, entry, entryPhonsOff);
			int cmp = entry.compare(word);
			if(cmp == 0) {
				return UnfoldPhons(entryPhonsOff);
			}
			if(cmp > 0) {
				break;
			}
		}
		return {};
	}

	void DictReader::EnumerateAll(
	    std::function<void(const std::string&, const std::vector<uint8_t>&)> callback) const {
		if(_restarts.empty()) {
			return;
		}
		int32_t	    wordOff  = (int32_t)_restarts[0].word;
		int32_t	    phonsOff = (int32_t)_restarts[0].phons;
		int32_t	    entryPhonsOff;
		std::string word;
		for(int32_t i = 0; i < _wordCount; i++) {
			ReadEntry(wordOff, phonsOff, word, entryPhonsOff);
			callback(word, UnfoldPhons(entryPhonsOff));
		}
	}

} // namespace SharpVox
